def apply(value, action):
    if action == "double":
        return value * 2
    return value - 1
def fold(actions, start):
    result = start
    for action in actions:
        result = apply(result, action)
    return result
steps = ["double", "minus", "double"]
print(fold(steps, 3))
steps[1] = "double"
print(fold(steps, 3))

def attach(state, number):
    state["items"].append(number)
    state["count"] = len(state["items"])
    return state["count"]
def summarize(state):
    return state["count"] + sum(state["items"])
shared = [1, 2]
data = {"items": shared, "count": 2}
print(attach(data, 4))
shared[0] = 3
print(summarize(data))
print(data["items"])

def add_to(bucket, name, value):
    bucket.setdefault(name, []).append(value)
    return len(bucket[name])
def evaluate(bucket, name):
    values = bucket.get(name, [])
    return sum(values) - len(values)
store = {}
print(add_to(store, "a", 3))
print(add_to(store, "a", 5))
print(add_to(store, "b", 4))
print(evaluate(store, "a"), evaluate(store, "b"))

def change(box, key, step):
    box[key]["value"] += step
    return box[key]["value"]
def score(box):
    return sum(item["value"] for item in box.values())
